import { useState } from "react";
import { ArrowUpRight } from "lucide-react";

import { addDays } from "../scarcity/model.ts";
import type { Evidence } from "../scarcity/model.ts";
import { formatDay, formatInstant, formatScore, formatWeekday, statusLabel } from "./format.ts";
import type { DayStatus } from "./format.ts";
import type { RestaurantDetailData } from "./ranking.functions.ts";

function SourceNotes({ evidence }: { evidence: Evidence[] }) {
  const unique = new Map(
    evidence.map((item) => [`${item.url}\n${item.observedAt}\n${item.quote}`, item]),
  );

  return (
    <ul className="source-notes">
      {[...unique].map(([key, item]) => {
        const url = new URL(item.url);

        return (
          <li key={key}>
            <blockquote>{item.quote}</blockquote>
            <p>
              {url.hostname === "api.resy.com" ? (
                <span>Captured Resy API response</span>
              ) : (
                <a href={item.url} target="_blank" rel="noreferrer">
                  {url.hostname} <ArrowUpRight size={12} aria-hidden="true" />
                </a>
              )}{" "}
              <span>· {formatInstant(item.observedAt)}</span>
            </p>
          </li>
        );
      })}
    </ul>
  );
}

export function RestaurantDetail({ detail }: { detail: RestaurantDetailData }) {
  const { restaurant, observations } = detail;
  const [selectedDate, setSelectedDate] = useState(addDays(restaurant.anchorDate, 1));
  const byDate = new Map(observations.map((observation) => [observation.diningDate, observation]));

  const days = Array.from({ length: 28 }, (_, index) => {
    const diningDate = addDays(restaurant.anchorDate, index + 1);
    const status: DayStatus = byDate.get(diningDate)?.status ?? "missing";

    return { diningDate, status };
  });

  const selected = byDate.get(selectedDate);
  const selectedStatus = selected?.status ?? "missing";
  const sourceEvidence = selected ? [...selected.evidence] : [];

  if (selected?.status === "unavailable")
    sourceEvidence.push(selected.releaseEvidence, selected.serviceEvidence);
  const showCalendar = restaurant.eligibility !== "excluded" && observations.length > 0;

  return (
    <article className="restaurant-detail" aria-label={`${restaurant.name} evidence`}>
      <header className="detail-heading">
        <p>{restaurant.address ?? "Street address not verified"}</p>
        <a href={restaurant.resyUrl} target="_blank" rel="noreferrer">
          Open on Resy <ArrowUpRight size={14} aria-hidden="true" />
        </a>
      </header>
      {restaurant.score === null ? (
        <p className="review-reason">
          {restaurant.eligibility === "eligible"
            ? restaurant.scoreReason
            : restaurant.eligibilityReason}
        </p>
      ) : null}
      {showCalendar ? (
        <div className="detail-grid">
          <section aria-label="Dinner availability by date">
            <div className="band-scores">
              {detail.bands.map((band) => (
                <div key={band.startDay}>
                  <span>
                    Days {band.startDay}–{band.endDay}
                  </span>
                  <strong>{band.score === null ? "—" : formatScore(band.score)}</strong>
                  <small>
                    {band.score === null
                      ? "Incomplete"
                      : `${band.unavailable}/${band.assessed} no opening`}
                  </small>
                </div>
              ))}
            </div>
            <div className="dinner-calendar">
              {days.slice(0, 7).map((day) => (
                <span className="weekday-label" key={day.diningDate}>
                  {formatWeekday(day.diningDate)}
                </span>
              ))}
              {days.map((day) => (
                <button
                  key={day.diningDate}
                  type="button"
                  data-status={day.status}
                  aria-pressed={day.diningDate === selectedDate}
                  aria-label={`${formatDay(day.diningDate)}: ${statusLabel[day.status]}`}
                  onClick={() => setSelectedDate(day.diningDate)}
                >
                  {Number(day.diningDate.slice(-2))}
                </button>
              ))}
            </div>
            <ul className="calendar-legend">
              <li>
                <span className="day-mark" data-status="available" />
                Available
              </li>
              <li>
                <span className="day-mark" data-status="unavailable" />
                No opening
              </li>
              <li>
                <span className="day-mark" data-status="non_service" />
                No service
              </li>
              <li>
                <span className="day-mark" data-status="unknown" />
                Unknown / unchecked
              </li>
            </ul>
          </section>
          <section className="date-evidence" aria-live="polite">
            <h2>
              {formatDay(selectedDate)} <span>{statusLabel[selectedStatus]}</span>
            </h2>
            {selected?.status === "available" ? (
              <p>
                Observed dinner starts:{" "}
                {[...new Set(selected.slots.map((slot) => slot.time))].join(", ")}. Local time,
                party of two.
              </p>
            ) : null}
            {selectedStatus === "missing" ? (
              <p>
                This date was not captured for this restaurant. It is not counted as unavailable.
              </p>
            ) : null}
            {selectedStatus === "unknown" ? (
              <p>
                The evidence does not establish availability or a released, unavailable dinner date.
                This date prevents a score for its week.
              </p>
            ) : null}
            {selectedStatus === "unavailable" ? (
              <p>
                No qualifying public dinner opening was observed. Release and regular service are
                supported by the sources below; this does not prove full occupancy.
              </p>
            ) : null}
            {selected ? (
              <p className="observed-at">Observed {formatInstant(selected.observedAt)}</p>
            ) : null}
            {sourceEvidence.length > 0 ? (
              <details className="evidence-disclosure">
                <summary>Evidence for this date</summary>
                <SourceNotes evidence={sourceEvidence} />
              </details>
            ) : null}
          </section>
        </div>
      ) : null}
      {restaurant.bookingPolicy ? (
        <p className="booking-policy">
          <strong>Booking policy.</strong> {restaurant.bookingPolicy}
        </p>
      ) : null}
      <details className="evidence-disclosure">
        <summary>Restaurant sources &amp; collection notes</summary>
        <SourceNotes evidence={detail.evidence} />
        <p className="collection-selection">{detail.collection.selection}</p>
        <ul className="collection-limitations">
          {detail.collection.limitations.map((limitation) => (
            <li key={limitation}>{limitation}</li>
          ))}
        </ul>
      </details>
    </article>
  );
}

import { Fragment, useState } from "react";
import { ArrowDown, ChevronRight, Search } from "lucide-react";

import { formatDay, formatScore, formatSnapshot, statusLabel } from "./format.ts";
import type { RankingData, RestaurantRow } from "./ranking.functions.ts";
import { RestaurantDetail } from "./restaurant-detail.tsx";

type Group = "ranked" | "review" | "excluded";

const groups: { id: Group; label: string }[] = [
  { id: "ranked", label: "Ranked" },
  { id: "review", label: "Needs review" },
  { id: "excluded", label: "Excluded" },
];

function groupOf(restaurant: Pick<RestaurantRow, "eligibility" | "score">): Group {
  if (restaurant.eligibility === "excluded") return "excluded";

  return restaurant.score === null ? "review" : "ranked";
}

function searchText(value: string) {
  return value
    .normalize("NFD")
    .replace(/\p{Diacritic}/gu, "")
    .toLowerCase();
}

export function RankingPage({
  data,
  expandedUrl,
  onToggle,
}: {
  data: RankingData;
  expandedUrl: string | undefined;
  onToggle: (url: string) => void;
}) {
  const [group, setGroup] = useState<Group>(() =>
    data.detail ? groupOf(data.detail.restaurant) : "ranked",
  );

  const [query, setQuery] = useState("");
  const counts: Record<Group, number> = { ranked: 0, review: 0, excluded: 0 };
  let snapshotDate: string | null = null;

  for (const row of data.restaurants) {
    counts[groupOf(row)]++;

    if (!snapshotDate || row.anchorDate > snapshotDate) snapshotDate = row.anchorDate;
  }

  const needle = searchText(query.trim());

  const rows = data.restaurants.filter(
    (row) =>
      groupOf(row) === group && searchText(`${row.name} ${row.address ?? ""}`).includes(needle),
  );

  return (
    <main className="ranking-page">
      <header className="ranking-header">
        <p className="eyebrow">RESY / SAN FRANCISCO</p>
        <h1>Hard-to-book restaurants</h1>
        <p className="scope">
          Party of two <span aria-hidden="true">·</span> Dinner, 6–9 p.m.{" "}
          <span aria-hidden="true">·</span> San Francisco time
        </p>
        <div className="snapshot-line">
          {snapshotDate ? (
            <span>Snapshot: {formatSnapshot(snapshotDate)}</span>
          ) : (
            <span>No data collected yet</span>
          )}
          <span className="coverage-note">Partial coverage, not a citywide ranking</span>
        </div>
        <details className="method">
          <summary>How the score works</summary>
          <div>
            <p>
              <strong>Score = 100 × dinner dates with no opening ÷ assessed dinner dates.</strong>{" "}
              Higher means harder access. We compare the same next seven calendar days, starting the
              day after each snapshot. Each date counts once; the number of slots does not affect
              the score.
            </p>
            <p>
              Confirmed non-service dates leave the denominator. A score needs every date accounted
              for and at least one dinner-service date. Unknown, unreleased, missing or failed dates
              prevent scoring. Closed venues, events, other-platform-only listings and venues
              outside SF do not earn scarcity points.
            </p>
            <p>
              The scale is fixed at 0–100, not a percentile. Later weeks provide context, not extra
              weight. This measures observed public Resy access, not occupancy, booking volume,
              prestige or a forecast. Open a restaurant to inspect its dates and sources.
            </p>
          </div>
        </details>
      </header>

      <section aria-label="Restaurant ranking">
        <div className="table-tools">
          <fieldset className="status-filters">
            <legend className="sr-only">Restaurant status</legend>
            {groups.map((item) => (
              <button
                key={item.id}
                type="button"
                aria-pressed={group === item.id}
                aria-label={`${item.label}: ${counts[item.id]} restaurants`}
                onClick={() => setGroup(item.id)}
              >
                {item.label} <span>{counts[item.id]}</span>
              </button>
            ))}
          </fieldset>
          <label className="restaurant-search">
            <Search size={16} aria-hidden="true" />
            <span className="sr-only">Search restaurants</span>
            <input
              type="search"
              placeholder="Search restaurants"
              value={query}
              onChange={(event) => setQuery(event.target.value)}
            />
          </label>
        </div>
        {group === "review" ? (
          <p className="group-note">
            Incomplete observations or unresolved Resy eligibility. These restaurants are not
            ranked; a missing score does not mean easy access.
          </p>
        ) : null}
        {group === "excluded" ? (
          <p className="group-note">
            Outside this comparison. Exclusion reasons are based on geography, service or booking
            evidence, not on empty calendars.
          </p>
        ) : null}
        <div className="ranking-table-wrap">
          <table className="ranking-table">
            <caption className="sr-only">
              {groups.find((item) => item.id === group)?.label} restaurants. Scored restaurants are
              ordered by scarcity, highest first. Equal scores are ties.
            </caption>
            <thead>
              <tr>
                <th scope="col">Restaurant</th>
                <th scope="col" aria-sort={group === "ranked" ? "descending" : undefined}>
                  Scarcity {group === "ranked" ? <ArrowDown size={12} aria-hidden="true" /> : null}
                </th>
                <th scope="col">No opening</th>
                <th scope="col" className="week-column">
                  Next 7 nights
                </th>
                <th scope="col" className="opening-column">
                  First opening seen
                </th>
              </tr>
            </thead>
            <tbody>
              {rows.map((restaurant) => {
                const expanded = expandedUrl === restaurant.resyUrl;

                return (
                  <Fragment key={restaurant.resyUrl}>
                    <tr className={expanded ? "expanded-row" : undefined}>
                      <td>
                        <button
                          className="restaurant-name"
                          type="button"
                          aria-expanded={expanded}
                          onClick={() => onToggle(restaurant.resyUrl)}
                        >
                          <ChevronRight
                            size={15}
                            aria-hidden="true"
                            className={expanded ? "chevron-open" : undefined}
                          />
                          <span>{restaurant.name}</span>
                        </button>
                        {group !== "ranked" ? (
                          <p className="row-reason">
                            {restaurant.eligibility === "eligible"
                              ? restaurant.scoreReason
                              : restaurant.eligibilityReason}
                          </p>
                        ) : null}
                      </td>
                      <td className="score-cell">
                        {restaurant.score === null ? (
                          <span className="unscored" aria-label="Not scored">
                            —
                          </span>
                        ) : (
                          <>
                            <span className="score-number">{formatScore(restaurant.score)}</span>
                            <div className="score-track" aria-hidden="true">
                              <span style={{ width: `${restaurant.score}%` }} />
                            </div>
                          </>
                        )}
                      </td>
                      <td className="fraction-cell">
                        {restaurant.score !== null ? (
                          <>
                            <span
                              title={`${restaurant.unavailable} of ${restaurant.assessed} assessed dinner dates had no qualifying opening`}
                            >
                              {restaurant.unavailable}
                              <span className="muted"> / {restaurant.assessed}</span>
                            </span>
                            {restaurant.nonService > 0 ? (
                              <small>{restaurant.nonService} non-service</small>
                            ) : null}
                          </>
                        ) : (
                          <span className="muted">—</span>
                        )}
                      </td>
                      <td className="week-column">
                        <div className="week-strip">
                          {restaurant.week.map((day) => (
                            <span
                              key={day.diningDate}
                              className="day-mark"
                              data-status={day.status}
                              title={`${formatDay(day.diningDate)}: ${statusLabel[day.status]}`}
                            >
                              <span className="sr-only">
                                {formatDay(day.diningDate)}: {statusLabel[day.status]}
                              </span>
                            </span>
                          ))}
                        </div>
                      </td>
                      <td className="opening-column first-opening">
                        {restaurant.earliestAvailableDate ? (
                          formatDay(restaurant.earliestAvailableDate)
                        ) : (
                          <span className="muted">Not observed</span>
                        )}
                      </td>
                    </tr>
                    {expanded && data.detail?.restaurant.resyUrl === restaurant.resyUrl ? (
                      <tr className="detail-row">
                        <td colSpan={5}>
                          <RestaurantDetail key={restaurant.resyUrl} detail={data.detail} />
                        </td>
                      </tr>
                    ) : null}
                  </Fragment>
                );
              })}
              {rows.length === 0 ? (
                <tr>
                  <td colSpan={5} className="empty-table">
                    {query
                      ? "No matching restaurants in this group. Try another name or status."
                      : "No restaurants in this group yet."}
                  </td>
                </tr>
              ) : null}
            </tbody>
          </table>
        </div>
        <footer className="table-footer">
          <span>
            {rows.length} restaurant{rows.length === 1 ? "" : "s"}
            {query ? " matching" : " shown"}
          </span>
          <span>0 = easy access observed. 100 = no qualifying opening on assessed dates.</span>
        </footer>
      </section>
    </main>
  );
}

import { and, eq, sql } from "drizzle-orm";

import * as tables from "../db/schema.ts";
import { addDays } from "../scarcity/model.ts";
import type { Observation } from "../scarcity/model.ts";
import { readRanking } from "../scarcity/store.ts";
import type { ScarcityDatabase } from "../scarcity/store.ts";

/** Summary rows stay small; only the opened restaurant includes slots and source quotes. */
export function readRankingPage(db: ScarcityDatabase, selectedUrl?: string) {
  return db.transaction((transaction) => {
    const rows = readRanking(transaction);

    const observedDays = transaction
      .select({
        resyUrl: tables.dinnerObservations.resyUrl,
        diningDate: tables.dinnerObservations.diningDate,
        status: tables.dinnerObservations.status,
      })
      .from(tables.dinnerObservations)
      .innerJoin(
        tables.restaurantRanking,
        and(
          eq(tables.restaurantRanking.resyUrl, tables.dinnerObservations.resyUrl),
          eq(tables.restaurantRanking.collectionId, tables.dinnerObservations.collectionId),
        ),
      )
      .where(
        sql`${tables.dinnerObservations.diningDate} <= date(${tables.restaurantRanking.anchorDate}, '+7 days')`,
      )
      .all();

    const daysByVenue = new Map<string, Map<string, Observation["status"]>>();

    for (const observation of observedDays) {
      const dates =
        daysByVenue.get(observation.resyUrl) ?? new Map<string, Observation["status"]>();

      dates.set(observation.diningDate, observation.status);
      daysByVenue.set(observation.resyUrl, dates);
    }

    const restaurants = rows.map((row) => ({
      resyUrl: row.resyUrl,
      name: row.name,
      address: row.address,
      anchorDate: row.anchorDate,
      eligibility: row.eligibility,
      eligibilityReason: row.eligibilityReason,
      score: row.score,
      scoreReason: row.scoreReason,
      unavailable: row.unavailable,
      assessed: row.assessed,
      nonService: row.nonService,
      earliestAvailableDate: row.earliestAvailableDate,
      week: Array.from({ length: 7 }, (_, index) => {
        const diningDate = addDays(row.anchorDate, index + 1);

        return {
          diningDate,
          status: daysByVenue.get(row.resyUrl)?.get(diningDate) ?? ("missing" as const),
        };
      }),
    }));

    const selected = rows.find((row) => row.resyUrl === selectedUrl);
    let detail = null;

    if (selected) {
      const identity = and(
        eq(tables.restaurantSnapshots.collectionId, selected.collectionId),
        eq(tables.restaurantSnapshots.resyUrl, selected.resyUrl),
      );

      const snapshot = transaction.select().from(tables.restaurantSnapshots).where(identity).get();

      const collection = transaction
        .select({
          id: tables.collections.id,
          selection: tables.collections.selection,
          limitations: tables.collections.limitations,
        })
        .from(tables.collections)
        .where(eq(tables.collections.id, selected.collectionId))
        .get();

      if (!snapshot || !collection) throw new Error("Ranking references a missing snapshot");
      detail = {
        restaurant: selected,
        evidence: snapshot.evidence,
        collection,
        observations: transaction
          .select({ detail: tables.dinnerObservations.detail })
          .from(tables.dinnerObservations)
          .where(
            and(
              eq(tables.dinnerObservations.collectionId, selected.collectionId),
              eq(tables.dinnerObservations.resyUrl, selected.resyUrl),
            ),
          )
          .orderBy(tables.dinnerObservations.diningDate)
          .all()
          .map((row) => row.detail),
        bands: transaction
          .select()
          .from(tables.scarcityScores)
          .where(
            and(
              eq(tables.scarcityScores.collectionId, selected.collectionId),
              eq(tables.scarcityScores.resyUrl, selected.resyUrl),
            ),
          )
          .orderBy(tables.scarcityScores.startDay)
          .all(),
      };
    }

    return { restaurants, detail };
  });
}

import { createHash } from "node:crypto";

import { desc, eq } from "drizzle-orm";
import type { BetterSQLite3Database } from "drizzle-orm/better-sqlite3";

import * as schema from "../db/schema.ts";
import { localDate, SCORE_VERSION } from "./model.ts";
import type { Collection } from "./model.ts";
import { scoreRestaurant } from "./score.ts";

export type ScarcityDatabase = BetterSQLite3Database<typeof schema>;

/** Import one validated, immutable collection atomically. Exact retries are no-ops. */
export function importCollection(db: ScarcityDatabase, collection: Collection) {
  const inputHash = createHash("sha256").update(JSON.stringify(collection)).digest("hex");
  const anchorDate = localDate(collection.startedAt);

  return db.transaction((transaction) => {
    const existing = transaction
      .select()
      .from(schema.collections)
      .where(eq(schema.collections.id, collection.id))
      .get();

    if (existing) {
      if (existing.inputHash !== inputHash) {
        throw new Error(
          `Collection ${collection.id} already exists with different evidence; use a new ID`,
        );
      }

      return { imported: false, restaurants: collection.restaurants.length };
    }

    transaction
      .insert(schema.collections)
      .values({
        id: collection.id,
        inputHash,
        schemaVersion: collection.schemaVersion,
        scoreVersion: SCORE_VERSION,
        startedAt: collection.startedAt,
        finishedAt: collection.finishedAt,
        anchorDate,
        discoveryUrl: collection.discoveryUrl,
        discoveryComplete: collection.discoveryComplete,
        selection: collection.selection,
        collector: collection.collector,
        procedure: collection.procedure,
        limitations: collection.limitations,
      })
      .run();

    for (const restaurant of collection.restaurants) {
      const { observations, ...assessment } = restaurant;
      const identity = { collectionId: collection.id, resyUrl: restaurant.resyUrl };
      transaction
        .insert(schema.restaurantSnapshots)
        .values({
          ...assessment,
          collectionId: collection.id,
        })
        .run();

      for (const observation of observations) {
        transaction
          .insert(schema.dinnerObservations)
          .values({
            ...identity,
            diningDate: observation.diningDate,
            observedAt: observation.observedAt,
            status: observation.status,
            detail: observation,
          })
          .run();
      }

      for (const band of scoreRestaurant(restaurant, anchorDate)) {
        transaction
          .insert(schema.scarcityScores)
          .values({
            ...identity,
            startDay: band.startDay,
            endDay: band.endDay,
            available: band.counts.available,
            unavailable: band.counts.unavailable,
            nonService: band.counts.non_service,
            unreleased: band.counts.unreleased,
            unknown: band.counts.unknown,
            collectionError: band.counts.collection_error,
            missing: band.counts.missing,
            assessed: band.assessed,
            score: band.score,
            reason: band.reason,
          })
          .run();
      }
    }

    return { imported: true, restaurants: collection.restaurants.length };
  });
}

export function readRanking(db: ScarcityDatabase) {
  // SQLite sorts NULL last with DESC. Equal scores remain ties, ordered by name for display.
  return db
    .select()
    .from(schema.restaurantRanking)
    .orderBy(desc(schema.restaurantRanking.score), schema.restaurantRanking.name)
    .all();
}

import Database from "better-sqlite3";
import { drizzle } from "drizzle-orm/better-sqlite3";
import { migrate } from "drizzle-orm/better-sqlite3/migrator";
import { expect, it, onTestFinished } from "vite-plus/test";

import * as schema from "../db/schema.ts";
import { readRankingPage } from "../ranking/ranking.server.ts";
import { addDays, collectionSchema, localDate, observationSchema } from "./model.ts";
import type { Observation, RestaurantCapture } from "./model.ts";
import { importCollection, readRanking } from "./store.ts";

const evidence = {
  url: "https://resy.com/cities/san-francisco-ca/venues/test-restaurant",
  observedAt: "2026-09-30T22:00:00.000Z",
  quote: "Synthetic test evidence; not a real restaurant observation.",
};

function openTestDatabase() {
  const sqlite = new Database(":memory:");
  onTestFinished(() => {
    sqlite.close();
  });
  sqlite.pragma("foreign_keys = ON");
  const db = drizzle(sqlite, { schema });
  migrate(db, { migrationsFolder: "drizzle" });

  return db;
}

function observation(offset: number, status: Observation["status"] = "available"): Observation {
  const base = {
    diningDate: addDays("2026-09-30", offset),
    observedAt: evidence.observedAt,
    evidence: [evidence],
  };

  if (status === "available") {
    return observationSchema.parse({
      ...base,
      status,
      slots: [{ time: "18:30", type: "Dining room", price: null }],
    });
  }

  if (status === "unavailable") {
    return observationSchema.parse({
      ...base,
      status,
      releaseEvidence: evidence,
      serviceEvidence: evidence,
    });
  }

  return observationSchema.parse({ ...base, status });
}

function restaurant(observations: Observation[]): RestaurantCapture {
  return {
    name: "Synthetic restaurant",
    resyUrl: evidence.url,
    address: "Synthetic SF address",
    geography: "san_francisco",
    eligibility: "eligible",
    reason: "Synthetic regular dinner service",
    bookingPolicy: "Synthetic 28-day release window",
    evidence: [evidence],
    observations,
  };
}

function collection(
  id: string,
  restaurants: RestaurantCapture[],
  startedAt = "2026-09-30T21:00:00Z",
) {
  return collectionSchema.parse({
    schemaVersion: 1,
    id,
    startedAt,
    finishedAt: "2026-09-30T22:10:00Z",
    discoveryUrl: "https://resy.com/cities/san-francisco-ca",
    discoveryComplete: false,
    selection: "Synthetic test fixtures only",
    collector: "test",
    procedure: ["Construct synthetic observations"],
    limitations: ["Not live evidence"],
    restaurants,
  });
}

it("scores a common week, excludes non-service dates, and retains later bands and inputs", () => {
  const db = openTestDatabase();

  const observations = [
    observation(1, "unavailable"),
    observation(2, "unavailable"),
    observation(3),
    observation(4),
    observation(5),
    observation(6, "non_service"),
    observation(7, "non_service"),
    ...Array.from({ length: 7 }, (_, index) => observation(index + 8, "unavailable")),
  ];

  importCollection(db, collection("first", [restaurant(observations)]));

  expect(readRanking(db)).toMatchObject([
    {
      score: 40,
      available: 3,
      unavailable: 2,
      assessed: 5,
      nonService: 2,
      earliestAvailableDate: "2026-10-03",
      weekendAvailableDates: 1,
    },
  ]);
  expect(db.select().from(schema.scarcityScores).all()).toMatchObject([
    { startDay: 1, score: 40 },
    { startDay: 8, score: 100 },
    { startDay: 15, score: null, missing: 7 },
    { startDay: 22, score: null, missing: 7 },
  ]);
  expect(db.select().from(schema.dinnerObservations).all()[0].detail).toEqual(observations[0]);
});

it.each(["unreleased", "unknown", "collection_error"] as const)(
  "does not publish a score when one dinner date is %s",
  (status) => {
    const db = openTestDatabase();

    const observations = Array.from({ length: 6 }, (_, index) =>
      observation(index + 1, "unavailable"),
    );

    observations.push(observation(7, status));
    importCollection(db, collection(status, [restaurant(observations)]));
    expect(readRanking(db)[0]).toMatchObject({ score: null, assessed: 6 });
  },
);

it("keeps missing dates and excluded restaurants unscored rather than interpreting absence as demand", () => {
  const db = openTestDatabase();
  const partial = restaurant([observation(1, "unavailable")]);

  const excluded = restaurant(
    Array.from({ length: 7 }, (_, index) => observation(index + 1, "unavailable")),
  );

  excluded.resyUrl = `${evidence.url}-excluded`;
  excluded.eligibility = "excluded";
  excluded.reason = "Event-only listing";
  importCollection(db, collection("partial", [partial, excluded]));
  expect(readRanking(db)).toMatchObject([{ score: null }, { score: null }]);
  expect(db.select().from(schema.scarcityScores).all()).toContainEqual(
    expect.objectContaining({
      resyUrl: partial.resyUrl,
      startDay: 1,
      missing: 6,
    }),
  );
});

it("retries imports without duplication, rejects changed evidence, and preserves snapshot history", () => {
  const db = openTestDatabase();

  const full = restaurant(
    Array.from({ length: 7 }, (_, index) => observation(index + 1, "unavailable")),
  );

  const first = collection("first", [full]);
  expect(importCollection(db, first).imported).toBe(true);
  expect(importCollection(db, first).imported).toBe(false);
  expect(db.select().from(schema.dinnerObservations).all()).toHaveLength(7);

  const changed = collection("first", [restaurant([])]);
  expect(() => importCollection(db, changed)).toThrow("different evidence");
  expect(readRanking(db)[0].score).toBe(100);

  const latest = collection("latest", [restaurant([])], "2026-09-30T20:00:00Z");
  latest.finishedAt = "2026-09-30T22:15:00.000Z";
  importCollection(db, collectionSchema.parse(latest));
  importCollection(db, collection("older-imported-last", [full], "2026-09-30T21:30:00Z"));
  expect(readRanking(db)[0]).toMatchObject({ collectionId: "latest", score: null, missing: 7 });
  const page = readRankingPage(db, evidence.url);
  expect(page.restaurants[0].week.map((day) => day.status)).toEqual(Array(7).fill("missing"));
  expect(page.detail).toMatchObject({
    collection: { id: "latest" },
    observations: [],
    bands: [
      { startDay: 1, score: null, missing: 7 },
      { startDay: 8 },
      { startDay: 15 },
      { startDay: 22 },
    ],
  });
  expect(readRankingPage(db).detail).toBeNull();
  expect(db.select().from(schema.restaurantSnapshots).all()).toHaveLength(3);
});

it("keeps a fixed score as the subset grows and sorts scored restaurants ahead of unresolved ones", () => {
  const db = openTestDatabase();

  const full = restaurant(
    Array.from({ length: 7 }, (_, index) => observation(index + 1, "unavailable")),
  );

  importCollection(db, collection("first", [full]));
  const open = restaurant(Array.from({ length: 7 }, (_, index) => observation(index + 1)));
  open.resyUrl = `${evidence.url}-open`;
  const unresolved = restaurant([]);
  unresolved.resyUrl = `${evidence.url}-unresolved`;
  unresolved.eligibility = "unresolved";
  importCollection(db, collection("expansion", [open, unresolved]));
  expect(readRanking(db).map((row) => row.score)).toEqual([100, 0, null]);
});

it("validates dates, geography, dinner times, and evidence at the import boundary", () => {
  const valid = collection("valid", [restaurant([observation(1)])]);
  const duplicate = structuredClone(valid);
  duplicate.restaurants[0].observations.push(observation(1));
  expect(collectionSchema.safeParse(duplicate).success).toBe(false);

  const outside = structuredClone(valid);
  outside.restaurants[0].geography = "outside_san_francisco";
  expect(collectionSchema.safeParse(outside).success).toBe(false);

  const past = structuredClone(valid);
  past.restaurants[0].observations[0].diningDate = "2026-09-30";
  expect(collectionSchema.safeParse(past).success).toBe(false);

  const event = structuredClone(valid);
  event.restaurants[0].resyUrl += "/events/special-dinner";
  expect(collectionSchema.safeParse(event).success).toBe(false);

  const futureEvidence = structuredClone(valid);
  futureEvidence.restaurants[0].evidence[0].observedAt = "2026-10-01T22:00:00Z";
  expect(collectionSchema.safeParse(futureEvidence).success).toBe(false);

  expect(
    observationSchema.safeParse({
      diningDate: "2026-10-01",
      observedAt: evidence.observedAt,
      status: "unavailable",
      evidence: [evidence],
    }).success,
  ).toBe(false);
  expect(
    observationSchema.safeParse({
      diningDate: "2026-10-01",
      observedAt: evidence.observedAt,
      status: "available",
      evidence: [evidence],
      slots: [{ time: "21:30", type: "Dinner", price: null }],
    }).success,
  ).toBe(false);
});

it("uses SF calendar dates across UTC midnight and daylight-saving changes", () => {
  expect(localDate("2026-10-01T01:00:00Z")).toBe("2026-09-30");
  expect(addDays("2026-10-31", 1)).toBe("2026-11-01");
